class RequestInterceptor implements HttpInterceptor {
 intercept(req: HttpRequest<any>, next: HttpHandler) {
  req = req.clone({ setHeaders: { Authorization: 'Bearer ' + localStorage.getItem('token') } })
  return next.handle(req)
 }
}

class Login { login(auth: any) { localStorage.setItem('token', auth.token) } }

class RequestInterceptor implements HttpInterceptor {
 intercept(req: HttpRequest<any>, next: HttpHandler) {
  req = req.clone({ setHeaders: { Authorization: 'Bearer ' + sessionStorage.getItem('token') } })
  return next.handle(req)
 }
}

class Login { login(auth: any) { sessionStorage.setItem('token', auth.token) } }
